mapper.select:
SELECT DISTINCT
TYPEUUID typeuuid,
ASSET_TYPE1 assetType1,
ASSET_TYPE2 assetType2,
ASSET_TYPE3 assetType3,
ASSET_BUSI_TYPE assetBusiType,
DEPT_CODE deptCode
FROM CHB_ASSET_TYPE_MAPPING A
WHERE 1=1

    AND A.ASSET_TYPE1 = #{assetType1,jdbcType=VARCHAR}


    AND A.ASSET_TYPE2 = #{assetType2,jdbcType=VARCHAR}


    AND A.ASSET_TYPE3 = #{assetType3,jdbcType=VARCHAR}


    AND A.ASSET_BUSI_TYPE = #{assetBusiType,jdbcType=VARCHAR}

SELECT ASSET_TYPE1, ASSET_TYPE2, ASSET_TYPE3, ASSET_BUSI_TYPE FROM CHB_ASSET_TYPE_MAPPING A
AND A.ASSET_TYPE1 = #{assetType1,jdbcType=VARCHAR}
AND A.ASSET_TYPE1 IS NULL
AND A.ASSET_TYPE2 = #{assetType2,jdbcType=VARCHAR}
AND A.ASSET_TYPE2 IS NULL
AND A.ASSET_TYPE3 = #{assetType3,jdbcType=VARCHAR}
AND A.ASSET_TYPE3 IS NULL
AND A.ASSET_BUSI_TYPE = #{assetBusiType,jdbcType=VARCHAR}
AND A.ASSET_BUSI_TYPE IS NULL
